  let wind = SAND_WIND;
  let toEye = frame.eye.xyz - in.at;
  let far = length(toEye);
  var point: SandPoint;
  point.at = in.at;
  point.h = in.shape.x;
  point.slope = in.shape.yz;
  // A swash sheet's edge is sharper than a triangle is small, so the sea is
