  let east = 1.0 / max(sceneAt(uv + vec2f(px.x, 0.0)).a, 0.05);
  let west = 1.0 / max(sceneAt(uv - vec2f(px.x, 0.0)).a, 0.05);
  let north = 1.0 / max(sceneAt(uv - vec2f(0.0, px.y)).a, 0.05);
  let south = 1.0 / max(sceneAt(uv + vec2f(0.0, px.y)).a, 0.05);
