  let stripe = select(0.0, band(h, 1.25, 0.2) + band(h, 0.05, 0.1), upright);
  let white = vec3f(0.6, 0.65, 0.63) * (0.88 + 0.12 * tile.y);
  let blue = vec3f(0.025, 0.15, 0.3) * (0.7 + 0.5 * tile.y);
