  let pipe = 1.0 - smoothstep(0.9, 1.0, abs(main));
  let body = sqrt(max(1.0 - main * main, 0.0));
  albedo = mix(albedo, vec3f(0.42, 0.04, 0.03) * (0.3 + 0.7 * body), pipe);
  gloss = mix(gloss, 0.4, pipe);
