  let tie = vec2f(spaced(s.uv.x, 1.2), spaced(h - 0.3, 0.7));
  let hole = 1.0 - smoothstep(0.016, 0.026, length(tie));
  let weep =
    (1.0 - smoothstep(0.0, 0.03, abs(tie.x)))
      * smoothstep(0.0, -0.3, tie.y)
      * step(tie.y, 0.0);
